class TransactionRow extends DataClass implements Insertable<TransactionRow> {
  final String id;

  /// Valeurs de `TransactionKind.storageValue`.
  final String kind;
  final int amount;

  /// Compte débité (dépense, transfert) ou crédité (revenu).
  final String accountId;

  /// Compte crédité d'un transfert ; `NULL` sinon.
  final String? toAccountId;

  /// Catégorie ou sous-catégorie ; `NULL` uniquement pour un transfert.
  final String? categoryId;
  final String? description;
  final int occurredAt;

  /// Mode de saisie (valeurs de `EntryMethod.storageValue`).
  final String entryMethod;

  /// Modèle récurrent qui a produit l'opération ; `NULL` si saisie à la main
  /// ou si le modèle a été supprimé.
  final String? recurringId;
  final int createdAt;
  final int updatedAt;
  const TransactionRow({
    required this.id,
    required this.kind,
    required this.amount,
    required this.accountId,
    this.toAccountId,
    this.categoryId,
